package org.apache.commons.codec.language;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.codec.EncoderException;
import org.apache.commons.codec.StringEncoder;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for Metaphone.metaphone to maximize branch and line coverage.
 */
public class Metaphone_metaphone_TriageGen1Test {

    private Metaphone metaphone;

    @Before
    public void setUp() {
        metaphone = new Metaphone();
    }

    @Test
    public void testNullOrEmpty() {
        assertEquals("", metaphone.metaphone(null));
        assertEquals("", metaphone.metaphone(""));
    }

    @Test
    public void testSingleCharacter() {
        assertEquals("A", metaphone.metaphone("a"));
        assertEquals("Z", metaphone.metaphone("z"));
    }

    @Test
    public void testInitialExceptions() {
        // K/G/P + N
        assertEquals("N", metaphone.metaphone("KN"));
        assertEquals("N", metaphone.metaphone("GN"));
        assertEquals("N", metaphone.metaphone("PN"));
        // K/G/P not N
        assertEquals("K", metaphone.metaphone("KA"));
        assertEquals("G", metaphone.metaphone("GA"));
        assertEquals("P", metaphone.metaphone("PA"));
        // A + E
        assertEquals("E", metaphone.metaphone("AE"));
        assertEquals("A", metaphone.metaphone("AX"));
        // W + R or H
        assertEquals("R", metaphone.metaphone("WR"));
        assertEquals("W", metaphone.metaphone("WH"));
        assertEquals("W", metaphone.metaphone("WA"));
        // X initial
        assertEquals("S", metaphone.metaphone("X"));
    }

    @Test
    public void testVowels() {
        // Only leading vowel should remain
        assertEquals("A", metaphone.metaphone("APPLE"));
        assertEquals("E", metaphone.metaphone("EGG"));
    }

    @Test
    public void testB() {
        assertEquals("B", metaphone.metaphone("BATH"));
        assertEquals("", metaphone.metaphone("MB")); // Silent B at end
    }

    @Test
    public void testC() {
        // SCI, SCE, SCY discard
        assertEquals("S", metaphone.metaphone("SCY"));
        assertEquals("S", metaphone.metaphone("SCE"));
        // CIA -> X
        assertEquals("X", metaphone.metaphone("CIA"));
        // CI, CE, CY -> S
        assertEquals("S", metaphone.metaphone("CITY"));
        assertEquals("S", metaphone.metaphone("CELL"));
        // SCH -> K
        assertEquals("K", metaphone.metaphone("SCH"));
        // CH vowel -> X
        assertEquals("X", metaphone.metaphone("CHAIR"));
        // CH consonant -> K (e.g., CHR)
        assertEquals("K", metaphone.metaphone("CHRONIC"));
        // Default C -> K
        assertEquals("K", metaphone.metaphone("CAT"));
    }

    @Test
    public void testD() {
        // DGE, DGI, DGY -> J
        assertEquals("J", metaphone.metaphone("DGE"));
        assertEquals("J", metaphone.metaphone("DGI"));
        assertEquals("J", metaphone.metaphone("DGY"));
        assertEquals("T", metaphone.metaphone("DOT"));
    }

    @Test
    public void testG() {
        // GH silent at end
        assertEquals("K", metaphone.metaphone("GHOST")); // GH before vowel
        assertEquals("K", metaphone.metaphone("GOUGH")); // GH at end
        // GH before consonant
        assertEquals("K", metaphone.metaphone("GHT"));
        // GN / GNED silent
        assertEquals("K", metaphone.metaphone("GNAT"));
        assertEquals("K", metaphone.metaphone("GNED"));
        // G + vowel (soft G) -> J
        assertEquals("J", metaphone.metaphone("GENTLE"));
        // G + consonant (hard G) -> K
        assertEquals("K", metaphone.metaphone("GOLF"));
        // Double G
        assertEquals("K", metaphone.metaphone("GIG"));
    }

    @Test
    public void testH() {
        assertEquals("H", metaphone.metaphone("HA")); // H + vowel
        assertEquals("T", metaphone.metaphone("TH")); // TH -> 0 (Logic check: T+H)
        // Note: the code uses regionMatch(local, n, "TH") which appends '0'
        assertEquals("0", metaphone.metaphone("TH"));
        // Terminal H
        assertEquals("A", metaphone.metaphone("AH"));
        // H after certain chars (VARSON check)
        // Assuming 'R' is in VARSON for coverage
        assertEquals("R", metaphone.metaphone("RH")); 
    }

    @Test
    public void testP() {
        assertEquals("F", metaphone.metaphone("PH"));
        assertEquals("P", metaphone.metaphone("PAT"));
    }

    @Test
    public void testQ() {
        assertEquals("K", metaphone.metaphone("QUEEN"));
    }

    @Test
    public void testS() {
        assertEquals("X", metaphone.metaphone("SHORE"));
        assertEquals("X", metaphone.metaphone("SIO"));
        assertEquals("X", metaphone.metaphone("SIA"));
        assertEquals("S", metaphone.metaphone("SUN"));
    }

    @Test
    public void testT() {
        assertEquals("X", metaphone.metaphone("TIA"));
        assertEquals("X", metaphone.metaphone("TIO"));
        assertEquals("T", metaphone.metaphone("TCH")); // TCH silent T
        assertEquals("T", metaphone.metaphone("TART"));
    }

    @Test
    public void testV() {
        assertEquals("F", metaphone.metaphone("VINE"));
    }

    @Test
    public void testWAndY() {
        assertEquals("W", metaphone.metaphone("WAY")); // W + vowel
        assertEquals("M", metaphone.metaphone("MY")); // Y + vowel
        assertEquals("M", metaphone.metaphone("MYTH")); // Y not followed by vowel (effectively)
    }

    @Test
    public void testX() {
        // X -> KS
        assertEquals("KS", metaphone.metaphone("XRAY"));
    }

    @Test
    public void testZ() {
        assertEquals("S", metaphone.metaphone("ZOO"));
    }

    @Test
    public void testMaxCodeLen() {
        metaphone.setMaxCodeLen(2);
        String res = metaphone.metaphone("METAPHONE");
        assertTrue(res.length() <= 2);
    }
}
